package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen1Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter writer;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        writer = new StringWriter();
    }

    @Test
    public void testTranslate_NotAnAmpersand() throws IOException {
        int result = unescaper.translate("abc", 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_AmpersandButNotHash() throws IOException {
        int result = unescaper.translate("&a", 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_AmpersandAtEnd() throws IOException {
        int result = unescaper.translate("&", 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_DecimalEntitySmall() throws IOException {
        // &#10; -> newline
        int result = unescaper.translate("&#10;", 0, writer);
        assertEquals(5, result);
        assertEquals("\n", writer.toString());
    }

    @Test
    public void testTranslate_DecimalEntityLarge() throws IOException {
        // &#65535; -> max BMP
        int result = unescaper.translate("&#65535;", 0, writer);
        assertEquals(7, result);
        assertEquals("\uFFFF", writer.toString());
    }

    @Test
    public void testTranslate_DecimalEntitySurrogate() throws IOException {
        // &#128512; -> 😀 (U+1F600)
        int result = unescaper.translate("&#128512;", 0, writer);
        assertEquals(8, result);
        assertEquals("\uD83D\uDE00", writer.toString());
    }

    @Test
    public void testTranslate_HexEntitySmall() throws IOException {
        // &#x0A; -> newline
        int result = unescaper.translate("&#x0A;", 0, writer);
        assertEquals(6, result);
        assertEquals("\n", writer.toString());
    }

    @Test
    public void testTranslate_HexEntityLarge() throws IOException {
        // &#x1F600; -> 😀
        int result = unescaper.translate("&#x1F600;", 0, writer);
        assertEquals(8, result);
        assertEquals("\uD83D\uDE00", writer.toString());
    }

    @Test
    public void testTranslate_HexEntityUppercaseX() throws IOException {
        // &#X41; -> A
        int result = unescaper.translate("&#X41;", 0, writer);
        assertEquals(6, result);
        assertEquals("A", writer.toString());
    }

    @Test
    public void testTranslate_NumberFormatException() throws IOException {
        // &#XYZ; is not a valid number
        int result = unescaper.translate("&#XYZ;", 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_HexNumberFormatException() throws IOException {
        // &#xG; is not a valid hex
        int result = unescaper.translate("&#xG;", 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_NoSemicolonEnd() throws IOException {
        // The code uses a while loop that expects a ';'
        // If ';' is missing, it might throw IndexOutOfBoundsException or loop infinitely.
        // Based on the provided logic: while(input.charAt(end) != ';') end++;
        // We test a valid case where it terminates.
        int result = unescaper.translate("&#65;", 0, writer);
        assertEquals(5, result);
        assertEquals("A", writer.toString());
    }
}
